svg.script:
// ─── Data & State ───────────────────────────────────────────────────
const ARRAY_SIZE = 20;
const BAR_AREA_W = 840;
const BAR_AREA_H = 300;
const BAR_GAP = 4;
const BAR_W = Math.floor((BAR_AREA_W - BAR_GAP * (ARRAY_SIZE + 1)) / ARRAY_SIZE);

let currentAlgo = 'bubble';
let animating = false;
let animTimeout = null;
let steps = [];
let stepIndex = 0;
let delay = 120;

const descriptions = {
  bubble: [
    "Bubble Sort repeatedly steps through the list, compares adjacent elements",
    "and swaps them if they are in the wrong order. The pass through the list",
    "is repeated until no swaps are needed, indicating that the list is sorted."
  ],
  selection: [
    "Selection Sort divides the list into a sorted and unsorted region. It",
    "repeatedly selects the smallest element from the unsorted region and",
    "moves it to the end of the sorted region."
  ],
  insertion: [
    "Insertion Sort builds the sorted array one element at a time by taking",
    "each element and inserting it into its correct position among the",
    "previously sorted elements."
  ],
  merge: [
    "Merge Sort divides the array in half recursively, sorts each half,",
    "then merges them back together. It uses a divide-and-conquer strategy",
    "guaranteeing O(n log n) performance in all cases."
  ],
  quick: [
    "Quick Sort selects a pivot element and partitions the array around it.",
    "Elements smaller than the pivot go left, larger go right. It then",
    "recursively sorts the sub-arrays on each side of the pivot."
  ]
};

const complexities = {
  bubble: { time: 'O(n²)', space: 'O(1)' },
  selection: { time: 'O(n²)', space: 'O(1)' },
  insertion: { time: 'O(n²)', space: 'O(1)' },
  merge: { time: 'O(n log n)', space: 'O(n)' },
  quick: { time: 'O(n log n)', space: 'O(log n)' }
};

// ─── Generate random array ───────────────────────────────────────────
function generateArray() {
  const arr = [];
  for (let i = 0; i < ARRAY_SIZE; i++) {
    arr.push(Math.floor(Math.random() * 90) + 10);
  }
  return arr;
}

let baseArray = generateArray();

// ─── SVG Helpers ────────────────────────────────────────────────────
const svgNS = "http://www.w3.org/2000/svg";

function getFill(state) {
  switch(state) {
    case 'compare': return 'url(#barCompare)';
    case 'swap':    return 'url(#barSwap)';
    case 'sorted':  return 'url(#barSorted)';
    case 'pivot':   return 'url(#barPivot)';
    default:        return 'url(#barDefault)';
  }
}

function renderBars(arr, highlights, sortedSet) {
  const g = document.getElementById('bars-group');
  while (g.firstChild) g.removeChild(g.firstChild);

  const maxVal = Math.max(...arr);

  arr.forEach((val, i) => {
    const barH = Math.floor((val / maxVal) * (BAR_AREA_H - 40));
    const x = BAR_GAP + i * (BAR_W + BAR_GAP);
    const y = BAR_AREA_H - barH - 10;

    let state = 'default';
    if (sortedSet && sortedSet.has(i)) state = 'sorted';
    if (highlights) {
      if (highlights.pivot === i) state = 'pivot';
      else if (highlights.swap && (highlights.swap[0] === i || highlights.swap[1] === i)) state = 'swap';
      else if (highlights.compare && (highlights.compare[0] === i || highlights.compare[1] === i)) state = 'compare';
    }

    // Bar
    const rect = document.createElementNS(svgNS, 'rect');
    rect.setAttribute('x', x);
    rect.setAttribute('y', y);
    rect.setAttribute('width', BAR_W);
    rect.setAttribute('height', barH);
    rect.setAttribute('rx', '3');
    rect.setAttribute('fill', getFill(state));
    if (state === 'compare' || state === 'swap' || state === 'pivot') {
      rect.setAttribute('filter', 'url(#glow)');
    }
    g.appendChild(rect);

    // Value label
    const txt = document.createElementNS(svgNS, 'text');
    txt.setAttribute('x', x + BAR_W / 2);
    txt.setAttribute('y', y - 4);
    txt.setAttribute('text-anchor', 'middle');
    txt.setAttribute('fill', state === 'default' ? '#c4b5fd' : 'white');
    txt.setAttribute('font-size', '10');
    txt.setAttribute('font-weight', 'bold');
    txt.textContent = val;
    g.appendChild(txt);

    // Index label
    const idx = document.createElementNS(svgNS, 'text');
    idx.setAttribute('x', x + BAR_W / 2);
    idx.setAttribute('y', BAR_AREA_H - 2);
    idx.setAttribute('text-anchor', 'middle');
    idx.setAttribute('fill', '#6b7280');
    idx.setAttribute('font-size', '9');
    idx.textContent = i;
    g.appendChild(idx);
  });
}

// ─── Sorting Algorithms → Steps ──────────────────────────────────────
function bubbleSortSteps(arr) {
  const a = [...arr];
  const steps = [];
  const sorted = new Set();
  let comps = 0, swps = 0;

  for (let i = 0; i < a.length; i++) {
    let swapped = false;
    for (let j = 0; j < a.length - i - 1; j++) {
      comps++;
      steps.push({ arr: [...a], highlights: { compare: [j, j+1] }, sorted: new Set(sorted), comps, swps, desc: `Comparing [${j}]=${a[j]} with [${j+1}]=${a[j+1]}` });
      if (a[j] > a[j+1]) {
        [a[j], a[j+1]] = [a[j+1], a[j]];
        swps++;
        swapped = true;
        steps.push({ arr: [...a], highlights: { swap: [j, j+1] }, sorted: new Set(sorted), comps, swps, desc: `Swapping! [${j}] ↔ [${j+1}]` });
      }
    }
    sorted.add(a.length - 1 - i);
    steps.push({ arr: [...a], highlights: {}, sorted: new Set(sorted), comps, swps, desc: `Element at position ${a.length - 1 - i} is now sorted ✓` });
    if (!swapped) break;
  }
  // Mark all sorted
  for (let k = 0; k < a.length; k++) sorted.add(k);
  steps.push({ arr: [...a], highlights: {}, sorted: new Set(sorted), comps, swps, desc: `Array fully sorted! Total comparisons: ${comps}, Swaps: ${swps}` });
  return steps;
}

function selectionSortSteps(arr) {
  const a = [...arr];
  const steps = [];
  const sorted = new Set();
  let comps = 0, swps = 0;

  for (let i = 0; i < a.length; i++) {
    let minIdx = i;
    steps.push({ arr: [...a], highlights: { pivot: i }, sorted: new Set(sorted), comps, swps, desc: `Finding minimum in unsorted portion starting at [${i}]` });

    for (let j = i + 1; j < a.length; j++) {
      comps++;
      steps.push({ arr: [...a], highlights: { compare: [minIdx, j], pivot: i }, sorted: new Set(sorted), comps, swps, desc: `Comparing current min [${minIdx}]=${a[minIdx]} with [${j}]=${a[j]}` });
      if (a[j] < a[minIdx]) {
        minIdx = j;
        steps.push({ arr: [...a], highlights: { compare: [minIdx, j], pivot: i }, sorted: new Set(sorted), comps, swps, desc: `New minimum found at [${minIdx}]=${a[minIdx]}` });
      }
    }

    if (minIdx !== i) {
      [a[i], a[minIdx]] = [a[minIdx], a[i]];
      swps++;
      steps.push({ arr: [...a], highlights: { swap: [i, minIdx] }, sorted: new Set(sorted), comps, swps, desc: `Swapping minimum [${minIdx}] with position [${i}]` });
    }
    sorted.add(i);
    steps.push({ arr: [...a], highlights: {}, sorted: new Set(sorted), comps, swps, desc: `Position [${i}] is sorted ✓` });
  }
  steps.push({ arr: [...a], highlights: {}, sorted: new Set(sorted), comps, swps, desc: `Array fully sorted! Comparisons: ${comps}, Swaps: ${swps}` });
  return steps;
}

function insertionSortSteps(arr) {
  const a = [...arr];
  const steps = [];
  const sorted = new Set([0]);
  let comps = 0, swps = 0;

  steps.push({ arr: [...a], highlights: {}, sorted: new Set(sorted), comps, swps, desc: `First element [0]=${a[0]} is trivially sorted` });

  for (let i = 1; i < a.length; i++) {
    let key = a[i];
    let j = i - 1;
    steps.push({ arr: [...a], highlights: { pivot: i }, sorted: new Set(sorted), comps, swps, desc: `Inserting element [${i}]=${key} into sorted portion` });

    while (j >= 0 && a[j] > key) {
      comps++;
      steps.push({ arr: [...a], highlights: { compare: [j, j+1] }, sorted: new Set(sorted), comps, swps, desc: `[${j}]=${a[j]} > ${key}, shift right` });
      a[j + 1] = a[j];
      swps++;
      steps.push({ arr: [...a], highlights: { swap: [j, j+1] }, sorted: new Set(sorted), comps, swps, desc: `Shifting [${j}]=${a[j]} to position [${j+1}]` });
      j--;
    }
    if (j >= 0) comps++;
    a[j + 1] = key;
    sorted.add(i);
    steps.push({ arr: [...a], highlights: { compare: [j+1, j+1] }, sorted: new Set(sorted), comps, swps, desc: `Placed ${key} at position [${j+1}] ✓` });
  }
  steps.push({ arr: [...a], highlights: {}, sorted: new Set(sorted), comps, swps, desc: `Array fully sorted! Comparisons: ${comps}, Swaps: ${swps}` });
  return steps;
}

function mergeSortSteps(arr) {
  const a = [...arr];
  const steps = [];
  const sorted = new Set();
  let comps = 0, swps = 0;

  function merge(arr, left, mid, right) {
    const leftArr = arr.slice(left, mid + 1);
    const rightArr = arr.slice(mid + 1, right + 1);
    let i = 0, j = 0, k = left;

    steps.push({ arr: [...arr], highlights: { compare: [left, right] }, sorted: new Set(sorted), comps, swps, desc: `Merging sub-arrays [${left}..${mid}] and [${mid+1}..${right}]` });

    while (i < leftArr.length && j < rightArr.length) {
      comps++;
      steps.push({ arr: [...arr], highlights: { compare: [left + i, mid + 1 + j] }, sorted: new Set(sorted), comps, swps, desc: `Compare ${leftArr[i]} vs ${rightArr[j]}` });
      if (leftArr[i] <= rightArr[j]) {
        arr[k] = leftArr[i++];
      } else {
        arr[k] = rightArr[j++];
        swps++;
      }
      steps.push({ arr: [...arr], highlights: { swap: [k, k] }, sorted: new Set(sorted), comps, swps, desc: `Placing ${arr[k]} at position [${k}]` });
      k++;
    }
    while (i < leftArr.length) { arr[k++] = leftArr[i++]; }
    while (j < rightArr.length) { arr[k++] = rightArr[j++]; }

    for (let x = left; x <= right; x++) sorted.add(x);
    steps.push({ arr: [...arr], highlights: {}, sorted: new Set(sorted), comps, swps, desc: `Sub-array [${left}..${right}] merged ✓` });
  }

  function mergeSort(arr, left, right) {
    if (left >= right) {
      sorted.add(left);
      return;
    }
    const mid = Math.floor((left + right) / 2);
    steps.push({ arr: [...arr], highlights: { compare: [left, right] }, sorted: new Set(sorted), comps, swps, desc: `Dividing [${left}..${right}] at mid=${mid}` });
    mergeSort(arr, left, mid);
    mergeSort(arr, mid + 1, right);
    merge(arr, left, mid, right);
  }

  mergeSort(a, 0, a.length - 1);
  for (let k = 0; k < a.length; k++) sorted.add(k);
  steps.push({ arr: [...a], highlights: {}, sorted: new Set(sorted), comps, swps, desc: `Array fully sorted! Comparisons: ${comps}, Operations: ${swps}` });
  return steps;
}

function quickSortSteps(arr) {
  const a = [...arr];
  const steps = [];
  const sorted = new Set();
  let comps = 0, swps = 0;

  function partition(arr, low, high) {
    const pivot = arr[high];
    let i = low - 1;
    steps.push({ arr: [...arr], highlights: { pivot: high }, sorted: new Set(sorted), comps, swps, desc: `Pivot = ${pivot} at [${high}]` });

    for (let j = low; j < high; j++) {
      comps++;
      steps.push({ arr: [...arr], highlights: { compare: [j, high], pivot: high }, sorted: new Set(sorted), comps, swps, desc: `Compare [${j}]=${arr[j]} with pivot=${pivot}` });
      if (arr[j] <= pivot) {
        i++;
        [arr[i], arr[j]] = [arr[j], arr[i]];
        swps++;
        steps.push({ arr: [...arr], highlights: { swap: [i, j], pivot: high }, sorted: new Set(sorted), comps, swps, desc: `${arr[j]} ≤ pivot, swap [${i}] ↔ [${j}]` });
      }
    }
    [arr[i + 1], arr[high]] = [arr[high], arr[i + 1]];
    swps++;
    steps.push({ arr: [...arr], highlights: { swap: [i+1, high] }, sorted: new Set(sorted), comps, swps, desc: `Place pivot at position [${i+1}]` });
    return i + 1;
  }

  function quickSort(arr, low, high) {
    if (low < high) {
      const pi = partition(arr, low, high);
      sorted.add(pi);
      steps.push({ arr: [...arr], highlights: {}, sorted: new Set(sorted), comps, swps, desc: `Pivot at [${pi}]=${arr[pi]} is in correct position ✓` });
      quickSort(arr, low, pi - 1);
      quickSort(arr, pi + 1, high);
    } else if (low === high) {
      sorted.add(low);
    }
  }

  quickSort(a, 0, a.length - 1);
  for (let k = 0; k < a.length; k++) sorted.add(k);
  steps.push({ arr: [...a], highlights: {}, sorted: new Set(sorted), comps, swps, desc: `Array fully sorted! Comparisons: ${comps}, Swaps: ${swps}` });
  return steps;
}

// ─── Run Algorithm ───────────────────────────────────────────────────
function runAlgorithm() {
  switch (currentAlgo) {
    case 'bubble':    return bubbleSortSteps(baseArray);
    case 'selection': return selectionSortSteps(baseArray);
    case 'insertion': return insertionSortSteps(baseArray);
    case 'merge':     return mergeSortSteps(baseArray);
    case 'quick':     return quickSortSteps(baseArray);
  }
}

// ─── Animation Loop ──────────────────────────────────────────────────
function playStep() {
  if (stepIndex >= steps.length) {
    setStatus('Done! ✓');
    animating = false;
    return;
  }
  const s = steps[stepIndex];
  renderBars(s.arr, s.highlights, s.sorted);
  document.getElementById('stat-comparisons').textContent = s.comps;
  document.getElementById('stat-swaps').textContent = s.swps;
  document.getElementById('step-desc').textContent = s.desc || '';
  setStatus(`Step ${stepIndex + 1} / ${steps.length}`);
  stepIndex++;
  animTimeout = setTimeout(playStep, delay);
}

function startAnimation() {
  if (animating) return;
  if (stepIndex >= steps.length) resetVisualization();
  animating = true;
  setStatus('Running...');
  playStep();
}

function stopAnimation() {
  animating = false;
  if (animTimeout) clearTimeout(animTimeout);
}

function resetVisualization() {
  stopAnimation();
  baseArray = generateArray();
  steps = runAlgorithm();
  stepIndex = 0;
  renderBars(baseArray, {}, new Set());
  document.getElementById('stat-comparisons').textContent = '0';
  document.getElementById('stat-swaps').textContent = '0';
  document.getElementById('step-desc').textContent = '';
  setStatus('Ready');
}

function setStatus(s) {
  document.getElementById('stat-status').textContent = s;
}

function updateComplexity() {
  const c = complexities[currentAlgo];
  document.getElementById('stat-complexity').textContent = c.time;
  document.getElementById('stat-space').textContent = c.space;
  const d = descriptions[currentAlgo];
  document.getElementById('desc-line1').textContent = d[0];
  document.getElementById('desc-line2').textContent = d[1];
  document.getElementById('desc-line3').textContent = d[2];
}

function selectAlgo(name) {
  const tabs = ['bubble','selection','insertion','merge','quick'];
  tabs.forEach(t => {
    const bg = document.getElementById('tab-'+t+'-bg');
    bg.setAttribute('fill', '#1e1b4b');
    bg.setAttribute('opacity', '0.7');
    const txt = bg.parentElement.querySelector('text');
    txt.setAttribute('fill', '#a0a0c0');
  });
  const selBg = document.getElementById('tab-'+name+'-bg');
  selBg.setAttribute('fill', '#6d28d9');
  selBg.setAttribute('opacity', '1');
  selBg.parentElement.querySelector('text').setAttribute('fill', 'white');

  currentAlgo = name;
  updateComplexity();
  resetVisualization();
}

function setDelay(d, btn) {
  delay = d;
  ['slow','fast','vfast'].forEach(b => {
    const bg = document.getElementById('btn-'+b+'-bg');
    bg.setAttribute('fill', '#1e1b4b');
    bg.parentElement.querySelector('text').setAttribute('fill', '#a0a0c0');
  });
  document.getElementById('btn-'+btn+'-bg').setAttribute('fill', '#4c1d95');
  document.getElementById('btn-'+btn+'-bg').parentElement.querySelector('text').setAttribute('fill', 'white');
}

// ─── Wire up events ──────────────────────────────────────────────────
document.getElementById('tab-bubble').addEventListener('click', () => selectAlgo('bubble'));
document.getElementById('tab-selection').addEventListener('click', () => selectAlgo('selection'));
document.getElementById('tab-insertion').addEventListener('click', () => selectAlgo('insertion'));
document.getElementById('tab-merge').addEventListener('click', () => selectAlgo('merge'));
document.getElementById('tab-quick').addEventListener('click', () => selectAlgo('quick'));

document.getElementById('btn-play').addEventListener('click', () => {
  if (animating) {
    stopAnimation();
    document.getElementById('btn-play').querySelector('text').textContent = '▶ PLAY';
  } else {
    startAnimation();
    document.getElementById('btn-play').querySelector('text').textContent = '⏸ PAUSE';
  }
});

document.getElementById('btn-reset').addEventListener('click', () => {
  document.getElementById('btn-play').querySelector('text').textContent = '▶ PLAY';
  resetVisualization();
});

document.getElementById('btn-slow').addEventListener('click', () => setDelay(400, 'slow'));
document.getElementById('btn-fast').addEventListener('click', () => setDelay(120, 'fast'));
document.getElementById('btn-vfast').addEventListener('click', () => setDelay(30, 'vfast'));

// ─── Initialize ──────────────────────────────────────────────────────
updateComplexity();
steps = runAlgorithm();
renderBars(baseArray, {}, new Set());
